SERVER_CARD = '{\n  "serverInfo": {\n    "name": "attest",\n    "version": "0.1.0"\n  },\n  "authentication": {\n    "required": false,\n    "schemes": []\n  },\n  "tools": [\n    {\n      "name": "verify_artifact",\n      "description": "Verify an artifact produced by an AI agent before accepting or paying for it. Four independent layers: schema conformance, whether there is anything inside (uniform lists, stubs, truncations), provenance bound to the artifact hash, and whether a signed mandate permitted the action. Returns a verdict (accept/review/reject), a 0-100 trust score, concrete findings and an Ed25519 signature. Rule-based, no LLM: the same artifact always yields the same result. Use before accepting work from another agent and before payment.",\n      "inputSchema": {\n        "type": "object",\n        "properties": {\n          "artifact": {\n            "description": "The agent artifact: object, array or string."\n          },\n          "schema": {\n            "type": "object",\n            "description": "Optional JSON Schema the artifact must satisfy."\n          },\n          "source": {\n            "type": "string",\n            "description": "Where the artifact came from, recorded in the attestation."\n          }\n        },\n        "required": [\n          "artifact"\n        ],\n        "additionalProperties": false\n      },\n      "annotations": {\n        "title": "Verify an AI agent artifact",\n        "readOnlyHint": true,\n        "destructiveHint": false,\n        "idempotentHint": true,\n        "openWorldHint": false\n      }\n    },\n    {\n      "name": "verify_artifact_batch",\n      "description": "Verify several artifacts at once — a scan report, a list of findings, a set of tool descriptions. One call, one verdict per artifact, plus a summary of how many were accepted, need review, or were rejected. Use when an agent produced a batch (twenty findings from a security scan, for example) and each of them has to be checked before the work is paid for.",\n      "inputSchema": {\n        "type": "object",\n        "properties": {\n          "artifacts": {\n            "type": "array",\n            "description": "The artifacts to verify: objects, arrays or strings."\n          },\n          "schema": {\n            "type": "object",\n            "description": "Optional JSON Schema every artifact must satisfy."\n          },\n          "source": {\n            "type": "string",\n            "description": "Where the artifacts came from, recorded in the attestations."\n          }\n        },\n        "required": [\n          "artifacts"\n        ],\n        "additionalProperties": false\n      },\n      "annotations": {\n        "title": "Verify a batch of AI agent artifacts",\n        "readOnlyHint": true,\n        "destructiveHint": false,\n        "idempotentHint": true,\n        "openWorldHint": false\n      }\n    },\n    {\n      "name": "bridge_check",\n      "description": "Settle a job between two agents through an escrow bridge. The client posts a task with a budget held in escrow, the worker delivers an artifact, the bridge verifies it and issues a signed RECEIPT. The budget is released only after verification passes. The RECEIPT is verifiable by a third party without access to the bridge, which is what makes it portable between worker, client and insurer. Actions: job (create), deliver (submit and verify), release (accept), refund (reject), verify (check someone else\'s receipt), trust (reputation). Use when an agent takes on paid work, or when you need to prove to a third party that the work was done.",\n      "inputSchema": {\n        "type": "object",\n        "properties": {\n          "action": {\n            "type": "string",\n            "enum": [\n              "job",\n              "deliver",\n              "release",\n              "refund",\n              "verify",\n              "trust"\n            ],\n            "description": "What to do."\n          },\n          "job_id": {\n            "type": "string",\n            "description": "Job ID (any action except job)."\n          },\n          "agent": {\n            "type": "string",\n            "description": "Agent identifier."\n          },\n          "title": {\n            "type": "string",\n            "description": "What needs to be done (for job)."\n          },\n          "spec": {\n            "type": "object",\n            "description": "Expected result specification (for job)."\n          },\n          "amount_minor": {\n            "type": "integer",\n            "description": "Budget in minor units; 1 USDC = 1000000."\n          },\n          "client": {\n            "type": "string",\n            "description": "Who the client is (for job)."\n          },\n          "artifact": {\n            "description": "The agent artifact (for deliver)."\n          },\n          "receipt": {\n            "type": "object",\n            "description": "A third party receipt (for verify)."\n          },\n          "db": {\n            "type": "string",\n            "description": "Path to the bridge database."\n          }\n        },\n        "required": [\n          "action"\n        ]\n      },\n      "annotations": {\n        "title": "Bridge: task to work to money",\n        "readOnlyHint": false,\n        "destructiveHint": false,\n        "idempotentHint": true,\n        "openWorldHint": true\n      }\n    }\n  ],\n  "resources": [],\n  "prompts": []\n}\n'
